#!/usr/bin/env python3
"""
write_reproduce_sh.py — emit a self-contained reproduce.sh for a run directory.

Produces a script that:
  1. Verifies the cwd is the right repo
  2. Checks the git commit matches metadata.json
  3. Activates the conda env
  4. Re-runs the exact training command from metadata.json

USAGE:
  python scripts/experiments/write_reproduce_sh.py --run-dir experiments/phase1.5_mappo_seed42
"""
from __future__ import annotations
import argparse
import json
import os
from pathlib import Path


TEMPLATE = """\
#!/bin/bash
# Auto-generated by scripts/experiments/write_reproduce_sh.py
# Reproduces run: {run_id}
# Commit: {commit}  dirty: {dirty}  seed: {seed}
set -euo pipefail

# 1. Verify cwd
REPO_DIR="$(cd "$(dirname "${{BASH_SOURCE[0]}}")/../../.." && pwd)"
cd "$REPO_DIR"
echo "[reproduce] cwd: $(pwd)"

# 2. Verify commit (warn if mismatch — don't fail; user may be intentionally re-running)
CURRENT_COMMIT=$(git rev-parse HEAD)
META_COMMIT="{commit}"
if [ "$CURRENT_COMMIT" != "$META_COMMIT" ]; then
    echo "[reproduce] WARN: HEAD ($CURRENT_COMMIT) != recorded commit ($META_COMMIT)"
    echo "[reproduce] Reproduction may differ. To use the recorded commit:"
    echo "    git checkout $META_COMMIT"
fi

# 3. Activate conda env
source /home/ubuntu/miniconda3/etc/profile.d/conda.sh
conda activate fluxphased

# 4. Re-run training
echo "[reproduce] running: {cmd}"
{cmd}

# 5. Re-parse metrics + regenerate figures
echo "[reproduce] regenerating metrics + figures"
RUN_DIR="$REPO_DIR/{run_dir_rel}"
python scripts/experiments/parse_log_to_metrics.py \\
    --log "$RUN_DIR/train.log" \\
    --out "$RUN_DIR/metrics.json" \\
    --run-id {run_id}
python scripts/experiments/make_figures.py \\
    --run {run_id}:"$RUN_DIR/metrics.json" \\
    --out-dir "$RUN_DIR/figures"
python scripts/experiments/write_agents_md.py --run-dir "$RUN_DIR" \\
    {baseline_arg}

echo "[reproduce] done.  See $RUN_DIR/AGENTS.md"
"""

BASH_BASELINE_ARG = '--baseline-dir experiments/phase1_pfsp_seed42'


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--run-dir", required=True, type=Path)
    ap.add_argument("--baseline-dir", type=Path,
                    default=Path("experiments/phase1_pfsp_seed42"))
    args = ap.parse_args()

    meta_path = args.run_dir / "metadata.json"
    if not meta_path.is_file():
        raise SystemExit(f"missing {meta_path} — run write_metadata.py first")
    meta = json.loads(meta_path.read_text(encoding="utf-8"))

    repo_root = Path(__file__).resolve().parents[2]  # scripts/experiments → scripts → repo
    run_dir_rel = args.run_dir.relative_to(repo_root) if args.run_dir.is_absolute() else args.run_dir
    baseline_arg = ""
    if args.run_dir.name != args.baseline_dir.name:
        baseline_arg = BASH_BASELINE_ARG

    script = TEMPLATE.format(
        run_id=meta["run_id"],
        commit=meta["git"]["commit"],
        dirty=meta["git"]["dirty"],
        seed=meta["seed"],
        cmd=meta["reproduce_cmd"],
        run_dir_rel=str(run_dir_rel),
        baseline_arg=baseline_arg,
    )

    out = args.run_dir / "reproduce.sh"
    out.write_text(script, encoding="utf-8")
    os.chmod(out, 0o755)
    print(f"wrote {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
